head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.clickListBzTpCd = ""; // 상장업무구분코드 (그리드 로우 클릭시 상장업무구분코드를 획득함)
scwin.clickBzProcsNo = ""; // 업무처리번호 (클릭된)
scwin.logicPackYn = "Y";
scwin.logicPackYn = "Y";
// 화면ID

scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.pre_newlisting.fn_initSearchDate(edt_ListSDate, edt_ListEDate);
        const usrCBData = "1주일전^1,1개월전^2,3개월전^3,6개월전^4,1년전^5,2년전^6";
        cmb_PeriodTp.CBData = usrCBData; // 사용자CBData 지정

        MaxTab_01.setSelectedTabIndex(1);
        await scwin.setCode();
        $c.cm.PanelToGroupBox(panel_Top);
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70015.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_1_OnLoadCompleted
 * @description dts_List_1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70015.dts_List_1_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_1_OnLoadError
 * @description dts_List_1 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_1_OnLoadError = function() {
    // alert('dts_List_1.OnLoadError()');

    // alert_error(dts_List_1);

};

/**
 * @method
 * @name dts_List_2_OnLoadCompleted
 * @description dts_List_2 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    try {
        // alert('dts_List_2.OnLoadCompleted('+rowcount+')');
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70015.dts_List_2_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_List_1_OnDblClick
 * @description grd_List_1 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_1_OnDblClick = async function(row, colid) {
    try {
        // 신규상장접수 > Grid Row Click
        if (colid === 'ISU_ABBRV') {
            await scwin.openNewWinForDgse(row, dts_List_1);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70015.grd_List_1_OnDblClick" });
    }
};

/**
 * @method
 * @name grd_List_2_OnDblClick
 * @description grd_List_2 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_2_OnDblClick = async function(row, colid) {
    try {
        // 신규상장접수 > Grid Row Click
        if (colid === 'ISU_ABBRV') {
            await scwin.openNewWinForDgse(row, dts_List_2);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70015.grd_List_2_OnDblClick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_ListSDate, edt_ListEDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70015.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name img_ReqEDate_onclick
 * @description img_ReqEDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ReqEDate_onclick = function() {
    try {
        popUpCalendar2(edt_ListEDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70015.img_ReqEDate_onclick" });
    }
};

/**
 * @method
 * @name img_ReqSDate_onclick
 * @description img_ReqSDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ReqSDate_onclick = function() {
    try {
        popUpCalendar2(edt_ListSDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70015.img_ReqSDate_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70015.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name img_IsuSearch_onclick
 * @description img_IsuSearch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_IsuSearch_onclick = function() {
    try {
        scwin.fn_SetPar = scwin.setParIsur2;
        scwin.fn_GetPar = scwin.getParIsur2;
        $c.lcd.fn_PopFindDigitalIsurAppl();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70015.img_IsuSearch_onclick" });
    }
};

/**
 * @method
 * @name MaxTab_01_OnSelChanged
 * @description Max Tab 01 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MaxTab_01_OnSelChanged = async function(nIndex) {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70015.MaxTab_01_OnSelChanged" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            txb_ISUR_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70015.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name txb_ISU_CD_onblur
 * @description txb_ISU_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISU_CD_onblur = function() {
    try {
        if (txb_ISU_CD.getValue() === "") {
            txb_ISU_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70015.txb_ISU_CD_onblur" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF70015.xml", SCREN_PROCS_TP_CD_07);
        scwin.excelDown();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70015.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name img_1_onclick
 * @description img_1 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_1_onclick = async function() {
    try {
        scwin.fn_SetPar = scwin.setParIsu;
        scwin.fn_GetPar = scwin.getParIsu;
        const options = {
            id: "ULDSTF70017_3",
            title: "종목 선택",
            type: "browserPopup",
            width: "430px",
            height: 550 + 30,
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("../digital/ULDSTF70017_3.gfm", options);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70015.img_1_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70015.btn_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 상장신청접수 에 대한 목록 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    let v_listBzTpCd = "";
    let urlcond = '';
    urlcond += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    urlcond += "&ISU_CD=" + txb_ISU_CD.getValue();
    urlcond += "&LIST_SDATE=" + edt_ListSDate.getValue();
    urlcond += "&LIST_EDATE=" + edt_ListEDate.getValue();
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        // 디지털증권 신규상장 청구
        v_listBzTpCd = "781";
        url += "?SCREN_ID=" + "ULDSTF70015.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listDigitalReceipt";
        url += "&inputMessageId=DIGITAL_LISTEDRCV_SEARCH_OUT";
        url += "&LIST_BZ_TP_CD=" + v_listBzTpCd;
        url += urlcond;
        const sbmOptions = {
            id : "sbm_dts_List_1",
            action : "/digital/DigitalListedRcv.do",
            ref : "",
            target : "dts_List_1=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        // 디지털증권 추가상장 청구
        v_listBzTpCd = "784";
        url += "?SCREN_ID=" + "ULDSTF70015.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listDigitalReceipt";
        url += "&inputMessageId=DIGITAL_LISTEDRCV_SEARCH_OUT";
        url += "&LIST_BZ_TP_CD=" + v_listBzTpCd;
        url += urlcond;
        const sbmOptions = {
            id : "sbm_dts_List_2",
            action : "/digital/DigitalListedRcv.do",
            ref : "",
            target : "dts_List_2=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_EtnInst",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_EtnInst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // alert("call");

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setBzProcsNo
 * @description (신규접수)클릭된 그리드에 대한 업무처리번호 획득
 * @param {Object} obj 컴포넌트
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function(obj, dtsObj) {
    scwin.clickBzProcsNo = dtsObj.getCellData(Number(obj), "BZ_PROCS_NO");
    scwin.clickListBzTpCd = dtsObj.getCellData(Number(obj), "LIST_BZ_TP_CD");
    // alert('clickListBzTpCd : ' + clickListBzTpCd );

};

/**
 * @method
 * @name openNewWinForDgse
 * @description 상장신청접수 에 대한 상세 팝업조회
 * @param {Number} row 행 인덱스
 * @param {*} dtsObj dtsObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openNewWinForDgse = async function(row, dtsObj) {
    scwin.setBzProcsNo(row, dtsObj);
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        const options = {
            id: "ULDSTF70050",
            title: "신규상장",
            type: "browserPopup",
            width: "1070px",
            height: "820px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/digital/ULDSTF70050.gfm", options);
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        const options = {
            id: "ULDSTF70051",
            title: "추가상장",
            type: "browserPopup",
            width: "1060px",
            height: "820px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/digital/ULDSTF70051.gfm", options);
    }
};

/**
 * @method
 * @name setParIsur2
 * @description 상장신청인 선택 팝업호출용
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParIsur2 = async function(arrPar) {
    let dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_ISUR_NM.setValue(arrPar[0].ISUR_NM);
        await scwin.listSync();
    }
};

/**
 * @method
 * @name setParIsu
 * @description 종목코드 선택 팝업호출용
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParIsu = async function(arrPar) {
    let dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_ABBRV);
        await scwin.listSync();
    }
};

/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        $c.data.downloadGridViewExcel(grd_List_1, {fileName: "신규상장목록", type: "8"});
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        $c.data.downloadGridViewExcel(grd_List_2, {fileName: "추가상장목록", type: "8"});
    }
};

/**
 * @method
 * @name initSearchDate
 * @description 신규/추가상장의 목록검색시작일과 종료일자의 초기값 설정
 * @param {*} edtSDate edtSDate
 * @param {*} edtEDate edtEDate
 * @returns {void}
 * @hidden N
 */
scwin.initSearchDate = function(edtSDate, edtEDate) {
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    edtSDate.setValue('19000101');
    edtEDate.setValue($c.ut.cGetPlusDate2(vCurDate, 60));
};

/**
 * @method
 * @name getParIsur2
 * @description get Par Isur2 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur2 = function(arrPar) {
    arrPar[0] = "lds.stf.digital.select.isuracptlist.condition";
    return arrPar.length;
};

/**
 * @method
 * @name getParIsu
 * @description get Par Isu 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsu = function(arrPar) {
    arrPar[0] = "lds.stf.digital.select.isuacptlist.condition";
    return arrPar.length;
};
